  private resetBall(playerId: string, hazard: ReturnType<HoleRuntime['hazardAt']>): void {
    if (!this.ball) return;
    const impact = { ...this.ball.position };
    const safe = this.holeSystem.getLastSafePosition(playerId, this.hole.spawn);
    const resolution = this.runtime?.resolveHazard(hazard, safe) ?? { resetPosition: safe, penaltyStrokes: 1 };
    this.ball.reset(resolution.resetPosition);
    this.runtime?.resetObstacles();
    this.effects.hazard(impact, hazard?.type ?? 'void');
    this.previousVelocity = undefined;
    this.match = this.matchManager.applySimulationEvent(this.match, this.course, {
      type: 'ball-reset',
      playerId,
      position: resolution.resetPosition,
      penaltyStrokes: resolution.penaltyStrokes,
    });
    this.toast((hazard ? 'HAZARD' : 'OUT OF BOUNDS') + ' · +' + String(resolution.penaltyStrokes));
    this.finishTurn(playerId, resolution.resetPosition);
  }

  private afterMatchUpdate(): void {
    if (this.match.phase === 'match-results') {
      this.showResults();
      return;
    }
    if (this.match.currentHoleIndex !== this.holeIndex) {
      this.loadHole(this.match.currentHoleIndex);
      return;
    }
    this.syncTurn();
  }

  private applyObstacleEffects(dt: number): void {
    const ball = this.ball;
    const runtime = this.runtime;
    // Aiming parks the ball on its last resting spot, so the volumes only act during a shot.
    if (!ball || !runtime || this.match.phase !== 'simulating') return;
    const effect = runtime.applyBallEffects(
      { position: ball.position, velocity: ball.velocity, radius: GAME_CONFIG.physics.ballRadius },
      dt,
      BALL_MASS,
    );
    if (!effect.changed) return;
    if (effect.position) {
      ball.body.setTranslation(effect.position, true);
      if (effect.clearAngularVelocity) ball.body.setAngvel({ x: 0, y: 0, z: 0 }, true);
    }
    ball.body.setLinvel(effect.velocity, true);
  }

  /** Rapier contacts are not surfaced here, so a hard direction flip marks a wall hit. */
  private trackImpacts(): void {
    const ball = this.ball;
    if (!ball) return;
    const velocity = ball.velocity;
    const previous = this.previousVelocity;
    this.previousVelocity = { x: velocity.x, y: velocity.y, z: velocity.z };
    if (!previous) return;
    const impact = detectBounce(previous, velocity);
    if (impact !== undefined) this.effects.bounce(ball.position, impact);
  }

  private applyRollingResistance(dt: number): void {
    const ball = this.ball;
    if (!ball) return;
    const deceleration = this.runtime?.decelerationAt(ball.position) ?? DEFAULT_DECELERATION;
    const rolled = rolledVelocity(ball.velocity, deceleration, dt);
    if (rolled) ball.body.setLinvel(rolled, true);
  }

  /** The director owns the reset key, the mode machine and the damping; feed it the ball. */
  private updateCamera(dt: number): void {
    this.cameraDirector.setFocus(this.ballPosition());
    applyCameraPose(this.options.camera, this.cameraDirector.update(dt, this.cameraView()));
  }

